// --- Inline button taps (callback_query) → same research path as typed /verify, /roadmap ---
const cq = $json.callback_query;
if (cq) {
  const cqChatId = cq.message?.chat?.id;
  const m = (cq.data || '').match(/^(verify|roadmap):([a-z0-9]{8})$/);
  if (!m || !cqChatId) {
    return [{ json: { chatId: cqChatId, callbackQueryId: cq.id, error: 'Unknown button.' } }];
  }
  return [{ json: {
    chatId: cqChatId,
    messageId: cq.message?.message_id,
    callbackQueryId: cq.id,
    _research_command: m[1],
    _research_text: '/' + m[1],
    _research_reply_text: 'id:' + m[2],
  }}];
}

const text = $json.message?.text ?? '';
const chatId = $json.message?.chat?.id;
const messageId = $json.message?.message_id;

if (!chatId) {
  return [{ json: { error: 'No chatId found in Telegram payload.' } }];
}

// --- NEW: research commands (/verify, /roadmap) bypass URL extraction ---
const researchMatch = text.match(/^\/(verify|roadmap)\b/i);
if (researchMatch) {
  return [{ json: {
    chatId,
    messageId,
    _research_command: researchMatch[1].toLowerCase(),
    _research_text: text,
    _research_reply_text: $json.message?.reply_to_message?.text || '',
  }}];
}

// --- existing /commands help ---
if (text.trim().toLowerCase() === '/commands') {
  return [{ json: { chatId, helpText: '<b>Available commands</b>\n\n' +
    '/summary &lt;url&gt; — Video summary (default)\n' +
    '/wisdom &lt;url&gt; — Key insights, quotes &amp; ideas\n' +
    '/chapters &lt;url&gt; — Timestamped chapter markers\n' +
    '/claims &lt;url&gt; — Fact-check claims in the video\n' +
    '/song &lt;url&gt; — Song meaning analysis\n' +
    '/verify (reply) — Codex web fact-check + second opinion\n' +
    '/roadmap (reply or URL) — Codex learning roadmap\n' +
    '/commands — Show this help\n\n' +
    '<b>Language flag</b> (optional):\n' +
    'Add <code>-xx</code> after the command for non-English videos.\n' +
    'Example: <code>/summary -es https://...</code>\n' +
    'Common: -es -de -fr -pt -it -nl -ja -ko -zh' } }];
}

const commands = {
  '/summary':  { pattern: 'youtube_summary',       label: 'Summary',         timestamps: false },
  '/wisdom':   { pattern: 'extract_wisdom',         label: 'Wisdom',          timestamps: false },
  '/chapters': { pattern: 'create_video_chapters',  label: 'Video Chapters',  timestamps: true  },
  '/claims':   { pattern: 'analyze_claims',          label: 'Claim Analysis',  timestamps: false },
  '/song':     { pattern: 'extract_song_meaning',   label: 'Song Meaning',    timestamps: false },
};

// Parse: /command [-lang] <url>
const cmdMatch = text.match(/^\/\w+/);
let pattern = 'youtube_summary';
let label = 'Summary';
let transcriptFlag = '--transcript';
let lang = '';

if (cmdMatch && commands[cmdMatch[0].toLowerCase()]) {
  const cmd = commands[cmdMatch[0].toLowerCase()];
  pattern = cmd.pattern;
  label = cmd.label;
  transcriptFlag = cmd.timestamps ? '--transcript-with-timestamps' : '--transcript';
}

// Check for language flag: -xx
const langMatch = text.match(/\s-([a-zA-Z]{2}(?:-[a-zA-Z]{2,3})?)\s/);
if (langMatch) lang = langMatch[1];

// Extract URL
const urlMatch = text.match(/(https?:\/\/(?:www\.)?(?:youtube\.com|youtu\.be|m\.youtube\.com)\/\S+)/);
if (!urlMatch) {
  return [{ json: { chatId, error: 'No YouTube URL found. Try: <code>/commands</code>' } }];
}

return [{ json: { chatId, youtubeUrl: urlMatch[1], pattern, label, transcriptFlag, lang } }];

const chatId = $node["Trigger: Telegram"].json.message.chat.id;
const url = $node["Params: YouTube"].json.youtubeUrl || '(unknown)';
const lang = $node["Params: YouTube"].json.lang || '';
const statusCode = $json.statusCode || 0;
const body = $json.body || {};
const detail = body.detail || 'Unknown error';

const esc = (s = '') => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let text;
if (statusCode === 404 || detail.includes('No captions') || detail.includes('disabled') || detail.includes('unavailable')) {
  text = '\u26a0\ufe0f <b>No subtitles available</b>\n\n' +
    '<b>URL:</b> ' + esc(url) + '\n' +
    (lang ? '<b>Language:</b> ' + esc(lang) + '\n' : '') +
    '\nThis video has no subtitles or auto-captions.';
} else if (statusCode === 429 || detail.includes('rate limit')) {
  text = '\u23f3 <b>YouTube rate limited</b>\n\n' +
    '<b>URL:</b> ' + esc(url) + '\n' +
    '\nTry again in a few minutes.';
} else {
  text = '\u274c <b>Transcript fetch failed</b>\n\n' +
    '<b>URL:</b> ' + esc(url) + '\n' +
    '<b>Error:</b> ' + esc(detail);
}

return [{ json: { chatId, text } }];

// Check for Fabric HTTP error
if ($json.statusCode >= 400) {
  return [{ json: { result: '', usage: {}, fabricError: 'Fabric returned HTTP ' + $json.statusCode } }];
}

const raw = ($json.data || $json.body || '').toString();

// Parse SSE response
const lines = raw.split('\n').filter(l => l.startsWith('data: '));
let content = '';
let usage = {};

for (const line of lines) {
  try {
    const obj = JSON.parse(line.slice(6));
    if (obj.type === 'content') content += obj.content;
    if (obj.type === 'usage') usage = obj.usage || {};
  } catch (e) {
    // skip unparseable lines
  }
}

if (!content) {
  return [{ json: { result: '', usage, fabricError: 'AI returned empty response' } }];
}

return [{ json: { result: content, usage } }];

const chatId = $node["Trigger: Telegram"].json.message.chat.id;
const label = $node["Params: YouTube"].json.label || 'Summary';
const youtubeUrl = $node["Params: YouTube"].json.youtubeUrl || '';

// Handle Fabric errors -- preserve existing behavior
if ($json.fabricError) {
  return [{ json: { chatId, chunk: '❌ <b>AI analysis failed</b>\n\n' + $json.fabricError } }];
}

let text = ($json.result ?? '').toString();
const rawAnalysis = text;  // pre-HTML, pre-strip -- this is what /verify will fact-check

// Remove ANSI colors
text = text.replace(/\x1b\[[0-9;]*m/g, '');
// Remove markdown bold
text = text.replace(/\*\*/g, '');
// Escape HTML
text = text
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .trim();

if (!text) {
  return [{ json: { chatId, chunk: '<b>' + label + '</b>\n\nNo content was returned.' } }];
}

// --- NEW: generate session id and persist for /verify and /roadmap lookup ---
const sessionId = Math.random().toString(36).slice(2, 10);
const TTL_MS = 7 * 86400 * 1000;
const CAP = 100;
const data = $getWorkflowStaticData('global');
if (typeof data.sessions !== 'object' || data.sessions === null) {
  data.sessions = {};
}
data.sessions[sessionId] = {
  video_url: youtubeUrl,
  gemini_analysis: rawAnalysis,
  created_at: Date.now(),
};
// Cleanup: TTL + hard cap
for (const [k, v] of Object.entries(data.sessions)) {
  if (!v || !v.created_at || Date.now() - v.created_at > TTL_MS) {
    delete data.sessions[k];
  }
}
const entries = Object.entries(data.sessions).sort((a, b) => b[1].created_at - a[1].created_at);
if (entries.length > CAP) {
  data.sessions = Object.fromEntries(entries.slice(0, CAP));
}

// Token usage
const usage = $json.usage || {};
const inTokens = usage.input_tokens || 0;
const outTokens = usage.output_tokens || 0;

// Cost calc (Gemini 2.5 Pro pricing)
const inCost = (inTokens / 1_000_000) * 1.25;
const outCost = (outTokens / 1_000_000) * 10.00;
const totalCost = inCost + outCost;

const fmtTokens = (n) => n >= 1000 ? (n / 1000).toFixed(1) + 'K' : String(n);
const costFooter = (inTokens || outTokens)
  ? `\n\n<i>~${fmtTokens(inTokens)} in / ~${fmtTokens(outTokens)} out | est. $${totalCost.toFixed(4)}</i>`
  : '';

// --- NEW: session footer goes on EVERY chunk so user can reply to any of them ---
const sessionFooter = `\n\n<i>─── /verify · /roadmap · id:${sessionId}</i>`;

const max = 3300;  // a bit smaller to fit both footers comfortably
const chunks = [];
for (let i = 0; i < text.length; i += max) chunks.push(text.slice(i, i + max));

return chunks.map((chunk, idx) => ({
  json: {
    chatId,
    sessionId,
    isLast: idx === chunks.length - 1,
    chunk: (idx === 0 ? `<b>${label}</b>\n\n` : '') +
           (chunks.length > 1 ? `Part ${idx + 1}/${chunks.length}\n\n` : '') +
           chunk +
           (idx === chunks.length - 1 ? costFooter : '') +
           sessionFooter,
  }
}));

const text = $json._research_text || '';
const replyText = $json._research_reply_text || '';
const chatId = $json.chatId;
const messageId = $json.messageId;
const command = $json._research_command;

// Extract URL from message (for /roadmap fresh URL)
const urlMatch = text.match(/(https?:\/\/(?:www\.)?(?:youtube\.com|youtu\.be|m\.youtube\.com)\/\S+)/);

// Branch A: /roadmap with fresh URL
if (command === 'roadmap' && urlMatch) {
  return [{ json: {
    command,
    chatId,
    messageId,
    via: 'fresh_url',
    video_url: urlMatch[1],
    gemini_analysis: '',
  }}];
}

// Branch B: reply-to with session id
const idMatch = replyText.match(/id:([a-z0-9]{8})/);
if (!idMatch) {
  const hint = command === 'verify'
    ? 'Reply to one of my analysis messages to use /verify.'
    : 'Reply to an analysis message, or pass a URL: <code>/roadmap https://youtu.be/...</code>';
  return [{ json: {
    _error_msg: hint,
    chatId,
    messageId,
  }}];
}

// Activity-driven cleanup on every read
const TTL_MS = 7 * 86400 * 1000;
const data = $getWorkflowStaticData('global');
if (typeof data.sessions !== 'object' || data.sessions === null) data.sessions = {};
for (const [k, v] of Object.entries(data.sessions)) {
  if (!v || !v.created_at || Date.now() - v.created_at > TTL_MS) delete data.sessions[k];
}

const session = data.sessions[idMatch[1]];
if (!session) {
  return [{ json: {
    _error_msg: 'That analysis is older than 7 days. Run /summary again to start fresh.',
    chatId,
    messageId,
  }}];
}

return [{ json: {
  command,
  chatId,
  messageId,
  via: 'reply',
  video_url: session.video_url,
  gemini_analysis: session.gemini_analysis || '',
}}];

