const r = $json;
const md = (r.markdown || '').toString().trim();
const tokens = r.tokens_used || 0;
const model = r.model || 'gpt';
const resolved = $('Code: Resolve Session').first().json;
const command = resolved.command;
const chatId = resolved.chatId;
const replyToMessageId = resolved.messageId;

const labelMap = { verify: '🔍 Verify', roadmap: '🗺️ Roadmap' };
const label = labelMap[command] || command;

// Minimal Markdown -> HTML for Telegram
function md2html(s) {
  // Escape HTML first
  s = s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  // ## headers -> <b>...</b>
  s = s.replace(/^##\s+(.+)$/gm, '<b>$1</b>');
  s = s.replace(/^#\s+(.+)$/gm, '<b>$1</b>');
  // **bold** -> <b>bold</b>
  s = s.replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>');
  return s;
}

const text = md2html(md);

const fmtTokens = (n) => n >= 1000 ? (n / 1000).toFixed(1) + 'K' : String(n);
const searches = r.searches || 0;
const footer = `\n\n<i>─── via ${model} · ${fmtTokens(tokens)} tokens${searches ? ' · ' + searches + ' searches' : ''}</i>`;
const max = 3400;
// Split on line boundaries: md2html only emits single-line tags, so a cut at
// "\n" can never leave a <b> open (a fixed-width cut did, and Telegram rejects it).
const chunks = [];
let rest = text;
while (rest.length > max) {
  let cut = rest.lastIndexOf('\n\n', max);
  if (cut < max * 0.5) cut = rest.lastIndexOf('\n', max);
  if (cut < max * 0.5) cut = max;
  chunks.push(rest.slice(0, cut).trimEnd());
  rest = rest.slice(cut).replace(/^\n+/, '');
}
chunks.push(rest);

return chunks.map((chunk, idx) => ({
  json: {
    chatId,
    replyToMessageId,
    chunk: (idx === 0 ? `<b>${label}</b>\n\n` : '') +
           (chunks.length > 1 ? `Part ${idx + 1}/${chunks.length}\n\n` : '') +
           chunk +
           (idx === chunks.length - 1 ? footer : ''),
  }
}));
